import json,re,sys,glob,yaml,collections
W="C:/visual projects/reverse-kit/pipeline/_work/run_sns/"
d=json.load(open(W+"index/index.json",encoding="utf-8"))
names=set()
for t in d["types"]: names.add(t["name"])
for f in d["fields"]: names.add(f["name"])
for m in d["methods"]: names.add(m["name"])
def ident_like(n):
    if len(n)<4 or n.startswith('.'): return False
    if '_' in n.strip('_'): return True
    return bool(re.search(r'[a-z][A-Z]',n)) or bool(re.match(r'^[A-Z][a-z]+[A-Z]',n))
ids={n for n in names if ident_like(n)}
KEYS={"title","behavior","own_name","goal","conditions","acceptance","open_questions"}
tok=re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
def walk(o,path,out,key=None):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,path+[k],out,k)
    elif isinstance(o,list):
        for v in o: walk(v,path,out,key)
    elif isinstance(o,str) and key in KEYS:
        for m in tok.finditer(o):
            if m.group() in ids: out.append((tuple(path),key,m.group()))
files=[f for f in glob.glob(W+"records/*/*.yaml") if not f.endswith("c-boss_patterns.yaml")]
tot=collections.Counter(); per=collections.defaultdict(list)
for f in files:
    y=yaml.safe_load(open(f,encoding="utf-8"))
    out=[]; walk(y,[],out)
    for o in out: tot[o[2]]+=1; per[f.split('/')[-1]].append(o)
print("violations",sum(tot.values()),"files",len(per),"unique",len(tot))
print(tot.most_common(60))
print({k:len(v) for k,v in per.items()})
json.dump({k:[list(x) if False else [list(map(str,x[0])),x[1],x[2]] for x in v] for k,v in per.items()},open("cr_before.json","w",encoding="utf-8"),ensure_ascii=False)
EOF
python cr.py

